mapper.select:
SELECT COUNT(*)
FROM PERF_KPI_SCORE
WHERE data_date = #{dataDate}
  AND scheme_code = #{schemeCode}

SELECT COUNT(*) FROM (
    SELECT 1
    FROM PERF_KPI_SCORE
    WHERE data_date = #{dataDate}
      AND scheme_code = #{schemeCode}
       AND subject_type = #{subjectType}

    GROUP BY subject_id, subject_type
) t

SELECT subject_id, subject_type, SUM(score) AS total_score
FROM PERF_KPI_SCORE
WHERE data_date = #{dataDate}
  AND scheme_code = #{schemeCode}
   AND subject_type = #{subjectType}

GROUP BY subject_id, subject_type
ORDER BY subject_id
LIMIT #{offset}, #{size}

SELECT id, data_date, scheme_code, metric_code, subject_type, subject_id,
       actual_value, weight, target_value, base_value, score
FROM PERF_KPI_SCORE
WHERE data_date = #{dataDate}
  AND scheme_code = #{schemeCode}
  AND (

      (subject_type = #{s.subjectType} AND subject_id = #{s.subjectId})

  )
